// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.emotionalimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.brain.memory.MemoryTypeimport timber.log.Timberimport java.time.Instantimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.math.exp/** * NOUS — Emotional Memory (Module 3 v2 — audit P0 fix). * * Strategy §3: "Emotional Memory (affective associations, 90-day decay with * Ebbinghaus curve)". * * Stores memories tagged with an emotional valence (positive/negative/neutral) * + intensity. Used by the Persona module to recall how the user felt about * past topics — "last time we discussed work, you were stressed". * * ## Ebbinghaus Decay * * Confidence decays exponentially over time: * ``` * decayedConfidence = originalConfidence * exp(-ageDays / 45) * ``` * where 45 is the half-life (confidence halves every ~45 days). After 90 days, * confidence is ~13% of original — effectively forgotten. * * ## Storage * * In-memory (session-scoped) for v1. A future migration will add a Room table * `emotional_memories` with 90-day auto-purge via WorkManager. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§2 Memory Architecture</a> */@Singletonclass EmotionalMemory @Inject constructor() {    private val entries = mutableListOf<EmotionalEntry>()    /**     * Record an emotional association with a memory.     *     * @param memory the memory that triggered the emotion.     * @param valence positive (1.0) → negative (-1.0), 0 = neutral.     * @param intensity 0.0-1.0 — how strongly the emotion was felt.     */    @Synchronized    fun record(memory: Memory, valence: Float, intensity: Float) {        require(valence in -1f..1f) { "valence must be in [-1,1], got $valence" }        require(intensity in 0f..1f) { "intensity must be in [0,1], got $intensity" }        val memoryId = memory.id ?: com.roshan.persona.brain.memory.MemoryId(System.nanoTime())        val entry = EmotionalEntry(            memoryId = memoryId,            content = memory.content,            valence = valence,            intensity = intensity,            recordedAt = memory.timestamp,            originalConfidence = memory.importance,        )        entries.add(entry)        Timber.tag(TAG).d("EmotionalMemory: recorded (valence=$valence, intensity=$intensity, total=${entries.size})")    }    /**     * Recall emotional associations for content matching [query].     *     * Returns entries sorted by decayed confidence (highest first).     * Entries with decayed confidence < 0.05 are filtered out (effectively forgotten).     */    @Synchronized    fun recall(query: String, limit: Int = 5): List<EmotionalEntry> {        val q = query.lowercase()        val now = Instant.now()        return entries            .filter { it.content.lowercase().contains(q) }            .map { it.copy(decayedConfidence = computeDecayedConfidence(it, now)) }            .filter { it.decayedConfidence >= 0.05f }            .sortedByDescending { it.decayedConfidence }            .take(limit)    }    /**     * Get the dominant emotion for a topic.     *     * Returns the average valence of all matching entries, weighted by decayed confidence.     * Returns null if no matching entries.     */    @Synchronized    fun dominantEmotion(query: String): EmotionalSummary? {        val matching = recall(query, limit = 50)        if (matching.isEmpty()) return null        val totalWeight = matching.sumOf { it.decayedConfidence.toDouble() }        if (totalWeight <= 0) return null        val weightedValence = matching.sumOf { (it.decayedConfidence * it.valence).toDouble() } / totalWeight        val avgIntensity = matching.sumOf { it.intensity.toDouble() } / matching.size        val label = when {            weightedValence > 0.3 -> EmotionLabel.POSITIVE            weightedValence < -0.3 -> EmotionLabel.NEGATIVE            else -> EmotionLabel.NEUTRAL        }        return EmotionalSummary(            label = label,            valence = weightedValence.toFloat(),            intensity = avgIntensity.toFloat(),            entryCount = matching.size,        )    }    /**     * Compute the decayed confidence using the Ebbinghaus curve.     *     * `decayed = original * exp(-ageDays / 45)`     *     * Half-life ≈ 31 days (ln(2) * 45 ≈ 31). After 90 days → ~13% of original.     */    private fun computeDecayedConfidence(entry: EmotionalEntry, now: Instant): Float {        val ageMs = now.toEpochMilli() - entry.recordedAt.toEpochMilli()        val ageDays = ageMs / (1000.0 * 60 * 60 * 24)        val decayFactor = exp(-ageDays / HALF_LIFE_DAYS)        return (entry.originalConfidence * decayFactor).toFloat()    }    /** Get total entry count (for diagnostics). */    @Synchronized    fun size(): Int = entries.size    /** Clear all entries (for tests). */    @Synchronized    fun clear() {        entries.clear()    }    private companion object {        private const val TAG = "EmotionalMemory"        /** Ebbinghaus decay half-life in days. confidence *= exp(-age/HALF_LIFE). */        private const val HALF_LIFE_DAYS = 45.0    }}/** * One emotional memory entry. */data class EmotionalEntry(    val memoryId: com.roshan.persona.brain.memory.MemoryId,    val content: String,    /** -1.0 (negative) to +1.0 (positive). 0 = neutral. */    val valence: Float,    /** 0.0-1.0 — how strongly the emotion was felt. */    val intensity: Float,    val recordedAt: Instant,    val originalConfidence: Float,    /** Computed on recall — decays over time. */    val decayedConfidence: Float = originalConfidence,)/** * Aggregated emotion summary for a topic. */data class EmotionalSummary(    val label: EmotionLabel,    val valence: Float,    val intensity: Float,    val entryCount: Int,)enum class EmotionLabel(val displayLabel: String) {    POSITIVE("Positive"),    NEGATIVE("Negative"),    NEUTRAL("Neutral"),}